        chosen = []
        # Preserve topology diversity among good regions.
        for net in ranked:
            if all(distance(net, other) >= 4 for other in chosen):
                chosen.append(net)
            if len(chosen) >= 18:
                break
        for net in ranked:
            if len(chosen) >= 30:
                break
            if net not in chosen:
                chosen.append(net)
        return chosen

    def select_parent(pop):
        # Balance quality, structural isolation, past productivity, and exploration.
        if len(pop) == 1:
            parent = pop[0]
        else:
            weights = []
            for rank, net in enumerate(pop):
                novelty = min(
                    (distance(net, other) for other in pop if other != net),
                    default=0,
                ) / max(1, 2 * n)
                underexplored = 1.0 / ((1.0 + parent_visits.get(net, 0)) ** 0.45)
                productive = 1.0 + min(1.0, 0.35 * parent_gains.get(net, 0))
                quality = 1.0 / (1.0 + 0.10 * rank)
                isolation = 0.75 + 0.5 * novelty
                weights.append(
                    quality * isolation * productive * underexplored
                    / (1.0 + 0.08 * stalls.get(net, 0))
                )
            pick = float(rng.random()) * sum(weights)
            parent = pop[-1]
            for net, weight in zip(pop, weights):
                pick -= weight
                if pick <= 0:
                    parent = net
                    break
