                continue

        for net in batch:
            changed = len(set(net) ^ set(parent))
            kind = "swap" if changed <= 4 else ("rotation" if changed <= 6 else "kick")
            operator_trials[kind] += 1
        batch_best = min((seen.get(net, float("inf")) for net in batch), default=float("inf"))
