                batch = screen(generate_moves(parent, detail, round_no), parent, width)

        # If the local neighborhood is exhausted, create a multi-switch kick.
        if not batch:
            for _ in range(50):
                current = set(parent)
                for _ in range(2 + int(rng.integers(4))):
