score 0.9901 on network12), copied from results/postproc_net12_run1/best/main.py. Only the fixed
wrapper below the EVOLVE block changed (tools.energy uses each pool's own Hamiltonian).
"""

"""Classical post-processing of QAOA output for QOBLIB 08. ShinkaEvolve edits the EVOLVE block."""

import json
import time

import numpy as np

# EVOLVE-BLOCK-START
def improve(demand, candidates, tools, rng):
    """Improve repaired candidate networks using an adaptive archive search."""
    n = tools.n
    scores = {}
    edge_sets = {}
    energies = {}
    visits = {}
    successes = {}
    stalls = {}
    best_net = None
    best_score = float("inf")
    scored_since_refresh = 0
    archive = []

    def canon(arcs):
        return tuple(sorted(tuple(map(int, arc)) for arc in arcs))

    def edge_set(net):
        if net not in edge_sets:
            edge_sets[net] = set(net)
        return edge_sets[net]

    def distance(a, b):
        return len(edge_set(a) ^ edge_set(b))

    def energy(net):
        if net not in energies:
            try:
                energies[net] = float(tools.energy(net))
            except Exception:
                energies[net] = 0.0
        return energies[net]

    def evaluate(net):
        nonlocal best_net, best_score, scored_since_refresh
        net = canon(net)
        if net not in scores:
            scores[net] = tools.lp(net)
            scored_since_refresh += 1
        value = scores[net]
        if value < best_score:
            best_net, best_score = net, value
        return value

    def refresh_archive():
        """Build a bounded archive containing both elites and distinct regions."""
        nonlocal archive
        ranked = sorted(scores, key=scores.get)
        selected = []

        # Establish a diverse elite core.
        for net in ranked:
            if all(distance(net, other) >= 4 for other in selected):
                selected.append(net)
            if len(selected) >= 22:
                break

        # Fill remaining capacity with the best available scored networks.
        for net in ranked:
            if len(selected) >= 44:
                break
            if net not in selected:
                selected.append(net)

        archive = selected

    def choose_parent():
        """Favor quality while giving under-explored and productive parents a chance."""
        if len(archive) == 1:
            return archive[0]

        weights = []
        for rank, net in enumerate(archive):
            quality = 1.0 / ((1.0 + rank) ** 0.58)
            exploration = 1.0 / ((1.0 + visits.get(net, 0)) ** 0.45)
            productivity = 1.0 + 0.65 * min(4, successes.get(net, 0))
            stale = 1.0 + min(1.5, 0.10 * stalls.get(net, 0))
            weights.append(quality * exploration * productivity * stale)

        total = sum(weights)
        pick = float(rng.random()) * total
        for net, weight in zip(archive, weights):
            pick -= weight
            if pick <= 0:
                return net
        return archive[-1]

    def two_switch(net, p, q):
        arcs = list(net)
        a, b = arcs[p]
        c, d = arcs[q]
        if a == d or c == b:
            return None

        current = edge_set(net)
        new1, new2 = (a, d), (c, b)
        if new1 in current or new2 in current:
            return None
        changed = current.copy()
        changed.remove((a, b))
        changed.remove((c, d))
        changed.add(new1)
        changed.add(new2)
        return tuple(sorted(changed))

    def propose(parent, detail):
        """Construct a mixed neighborhood centered on loaded or priced links."""
        arcs = list(parent)
        current = edge_set(parent)
        moves = set()

        prices = detail.get("prices", {}) if detail else {}
        hot = {
            tuple(map(int, link))
            for link, price in prices.items()
            if float(price) > 0
        }
        loads = detail.get("loads", {}) if detail else {}
        if loads:
            by_load = sorted(
                ((float(value), tuple(map(int, link)))
                 for link, value in loads.items()),
                reverse=True,
            )
            hot.update(link for _, link in by_load[:6])

        # Enumerate all valid switches touching at least one critical link.
        for p in range(len(arcs)):
            for q in range(p + 1, len(arcs)):
                if hot and arcs[p] not in hot and arcs[q] not in hot:
                    continue
                move = two_switch(parent, p, q)
                if move is not None:
                    moves.add(move)

        # Include unrestricted switches to reduce dependence on LP dual prices.
        for _ in range(65):
            p = int(rng.integers(len(arcs)))
            q = int(rng.integers(len(arcs) - 1))
            if q >= p:
                q += 1
            move = two_switch(parent, p, q)
            if move is not None:
                moves.add(move)

        # Degree-preserving three-link rotations.
        for _ in range(75):
            ids = rng.choice(len(arcs), size=3, replace=False)
            (a, b), (c, d), (e, f) = (arcs[int(i)] for i in ids)
            old = {(a, b), (c, d), (e, f)}
            if hot and not (old & hot):
                continue
            for new in (
                {(a, d), (c, f), (e, b)},
                {(a, f), (c, b), (e, d)},
            ):
                if len(new) != 3 or any(u == v for u, v in new):
                    continue
                if new & (current - old):
                    continue
                moves.add(tuple(sorted((current - old) | new)))

        # Occasionally add a short path toward another elite network.
        targets = [
            net for net in archive
            if net != parent and distance(net, parent) >= 6
        ]
        if targets:
            target = targets[int(rng.integers(len(targets)))]
            target_edges = edge_set(target)
            path = parent
            for _ in range(4):
                path_arcs = list(path)
                overlap = len(edge_set(path) & target_edges)
                improving = []
                for p in range(len(path_arcs)):
                    for q in range(p + 1, len(path_arcs)):
                        move = two_switch(path, p, q)
                        if move is not None:
                            gain = len(edge_set(move) & target_edges) - overlap
                            if gain > 0:
                                improving.append((gain, move))
                if not improving:
                    break
                best_gain = max(gain for gain, _ in improving)
                choices = [move for gain, move in improving if gain == best_gain]
                path = choices[int(rng.integers(len(choices)))]
                moves.add(path)

        # A few multi-switch perturbations help leave one-switch basins.
        for _ in range(16):
            changed = set(parent)
            for _ in range(2 + int(rng.integers(4))):
                now = list(changed)
                p, q = rng.choice(len(now), size=2, replace=False)
                a, b = now[int(p)]
                c, d = now[int(q)]
                if a == d or c == b or (a, d) in changed or (c, b) in changed:
                    continue
                changed.remove((a, b))
                changed.remove((c, d))
                changed.add((a, d))
                changed.add((c, b))
            if changed != current:
                moves.add(tuple(sorted(changed)))

        return [
            net for net in moves
            if net != parent
            and net not in scores
            and not tools.is_cached(net)
            and tools.is_valid(net)
        ]

    def select_batch(moves, parent, limit=3):
        """Spend LP calls on a blend of promising and structurally distinct moves."""
        if not moves:
            return []

        base_energy = energy(parent)
        ranked = sorted(moves, key=lambda net: energy(net) - base_energy)
        selected = []

        # First take surrogate-favored moves with meaningful topology differences.
        for net in ranked:
            if all(distance(net, old) >= 2 for old in selected):
                selected.append(net)
            if len(selected) >= min(2, limit):
                break

        # Use remaining capacity for a randomly selected part of the ranked tail.
        remaining = [net for net in ranked if net not in selected]
        if remaining and len(selected) < limit:
            head_count = max(8, 3 * limit)
            head = remaining[:head_count]
            tail = remaining[head_count:]
            rng.shuffle(tail)
            pool = head + tail
            while pool and len(selected) < limit:
                selected.append(pool.pop(0))
        return selected[:limit]

    # Repair all samples without spending LP calls, then choose diverse,
    # low-energy seeds for initial evaluation.
    repaired = set()
    for candidate in candidates:
        try:
            net = canon(tools.repair(candidate))
            if tools.is_valid(net):
                repaired.add(net)
        except Exception:
            continue

    if not repaired:
        try:
            net = canon(tools.repair([]))
            if tools.is_valid(net):
                repaired.add(net)
        except Exception:
            return []

    ranked_seeds = sorted(repaired, key=energy)
    seeds = []
    for net in ranked_seeds:
        if all(distance(net, other) >= 4 for other in seeds):
            seeds.append(net)
        if len(seeds) >= 24:
            break
    for net in ranked_seeds:
        if len(seeds) >= 36:
            break
        if net not in seeds:
            seeds.append(net)

    for net in seeds:
        if tools.lp_calls_left <= 0:
            break
        try:
            evaluate(net)
        except Exception as exc:
            if type(exc).__name__ == "BudgetExhausted":
                break
            continue

    if not scores:
        return list(seeds[0])

    refresh_archive()

    while tools.lp_calls_left > 0:
        if scored_since_refresh >= 12:
            refresh_archive()
            scored_since_refresh = 0

        parent = choose_parent()
        visits[parent] = visits.get(parent, 0) + 1

        try:
            detail = tools.lp_detail(parent)
        except Exception:
            detail = None

        batch = select_batch(propose(parent, detail), parent)

        # If this neighborhood is exhausted, try another lightly visited archive member.
        if not batch:
            alternatives = sorted(
                (net for net in archive if net != parent),
                key=lambda net: visits.get(net, 0),
            )
            for alternative in alternatives[:8]:
                try:
                    alt_detail = tools.lp_detail(alternative)
                except Exception:
                    alt_detail = None
                batch = select_batch(propose(alternative, alt_detail), alternative)
                if batch:
                    parent = alternative
                    visits[parent] = visits.get(parent, 0) + 1
                    break

        # Last-resort kick to avoid stalling when generated neighborhoods are exhausted.
        if not batch:
            for _ in range(40):
                changed = set(parent)
                for _ in range(3 + int(rng.integers(4))):
                    now = list(changed)
                    p, q = rng.choice(len(now), size=2, replace=False)
                    a, b = now[int(p)]
                    c, d = now[int(q)]
                    if a == d or c == b or (a, d) in changed or (c, b) in changed:
                        continue
                    changed.remove((a, b))
                    changed.remove((c, d))
                    changed.add((a, d))
                    changed.add((c, b))
                kicked = tuple(sorted(changed))
                if (
                    kicked != parent
                    and kicked not in scores
                    and not tools.is_cached(kicked)
                    and tools.is_valid(kicked)
                ):
                    batch = [kicked]
                    break

        if not batch:
            break

        parent_score = scores.get(parent, float("inf"))
        previous_best = best_score
        best_child = float("inf")

        for net in batch:
            if tools.lp_calls_left <= 0:
                break
            try:
                value = evaluate(net)
                best_child = min(best_child, value)
            except Exception as exc:
                if type(exc).__name__ == "BudgetExhausted":
                    return list(best_net) if best_net is not None else []
                continue

        if best_child < parent_score:
            stalls[parent] = 0
            successes[parent] = successes.get(parent, 0) + 1
        else:
            stalls[parent] = stalls.get(parent, 0) + 1

        if best_score < previous_best:
            successes[parent] = successes.get(parent, 0) + 1

    return list(best_net) if best_net is not None else []
# EVOLVE-BLOCK-END


def run_postproc(pool_path, lp_budget, seed, control=False, time_limit=150):
    """Fixed entry point called by the evaluator: one run on one candidate pool."""
    import importlib.util
    import signal
    from pathlib import Path

    import oracle

    pool = json.load(open(pool_path))
    import qoblib_tools as qt

    if "hamiltonian_file" in pool:  # the Hamiltonian that sampled this pool (make_pools.py --tag)
        spec = importlib.util.spec_from_file_location(
            f"hamiltonian_{pool['hamiltonian_tag']}", Path(pool_path).resolve().parent / pool["hamiltonian_file"])
        ham = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(ham)
        surrogate_terms = ham.surrogate_terms
    else:  # older pools: the frozen run 3 gen 28 Hamiltonian
        from hamiltonian import surrogate_terms

    n = int(pool["instance"][-2:])
    demand = qt.load_network_demand(n)
    linear, quadratic, _ = surrogate_terms(np.array(demand, dtype=float))
    tools = oracle.Tools(demand, lp_budget, (
        {tuple(map(int, a)): float(w) for a, w in linear.items()},
        {(tuple(map(int, a)), tuple(map(int, b))): float(w) for (a, b), w in quadratic.items()},
    ))
    candidates = [[tuple(map(int, a)) for a in c["arcs"]] for c in pool["candidates"]]
    if control:  # same number of random valid networks instead of QAOA output
        crng = np.random.default_rng(10_000 + seed)
        candidates = [qt.random_topology(n, crng) for _ in candidates]
    def _timeout(signum, frame):
        raise oracle.RunTimeout()

    start = time.perf_counter()
    returned, error, timed_out = None, None, False
    signal.signal(signal.SIGALRM, _timeout)
    signal.alarm(int(time_limit))
    try:
        returned = improve(demand.copy(), candidates, tools, np.random.default_rng(seed))
    except oracle.BudgetExhausted:
        pass
    except oracle.RunTimeout:
        timed_out = True
    except Exception as exc:  # noqa: BLE001
        error = f"{type(exc).__name__}: {exc}"
    finally:
        signal.alarm(0)
    best_score, best_arcs = tools.certified_best()
    if returned is not None:
        try:
            ret = [tuple(map(int, a)) for a in returned]
            if qt.is_valid_topology(n, ret):
                s = qt.route_min_congestion(demand, ret).objective
                if s < best_score:
                    best_score, best_arcs = s, tuple(sorted(ret))
        except Exception:  # noqa: BLE001
            pass
    return {
        "pool": pool_path, "control": control, "n": n, "error": error,
        "best": float(best_score), "arcs": [list(a) for a in best_arcs] if best_arcs else None,
        "lp_calls": tools.lp_calls_used, "seconds": time.perf_counter() - start, "timed_out": timed_out,
    }

