"""Classical post-processing of QAOA output for QOBLIB 08. ShinkaEvolve edits the EVOLVE block."""

import json
import time

import numpy as np

# EVOLVE-BLOCK-START
import math


def improve(demand, candidates, tools, rng):
    """Search repaired QAOA networks using a surrogate-screened diverse archive."""
    n = tools.n
    seen = {}
    best_net = None
    best_score = float("inf")
    parent_stalls = {}
    parent_visits = {}
    parent_improvements = {}

    def canon(arcs):
        return tuple(sorted(tuple(map(int, a)) for a in arcs))

    def evaluate(net):
        """Score once locally; budget exhaustion is allowed to reach the caller."""
        nonlocal best_net, best_score
        net = canon(net)
        if net not in seen:
            seen[net] = tools.lp(net)
        s = seen[net]
        if s < best_score:
            best_net, best_score = net, s
        return s

    def energy(net):
        try:
            return float(tools.energy(net))
        except Exception:
            return 0.0

    def distance(a, b):
        return len(set(a) ^ set(b))

    def choose_starts(repaired, limit):
        """Prefer low surrogate energy, while retaining topological variety."""
        ordered = sorted(repaired, key=energy)
        chosen = []
        for net in ordered:
            if all(distance(net, old) >= 4 for old in chosen):
                chosen.append(net)
            if len(chosen) >= limit:
                break
        for net in ordered:
            if len(chosen) >= limit:
                break
            if net not in chosen:
                chosen.append(net)
        return chosen

    # Repair all raw samples for free, then seed the search with a compact,
    # energy-ranked but diversity-aware subset.
    repaired = set()
    for cand in candidates:
        try:
            net = canon(tools.repair(cand))
            if tools.is_valid(net):
                repaired.add(net)
        except Exception:
            continue

    if not repaired:
        try:
            net = canon(tools.repair([]))
            if tools.is_valid(net):
                repaired.add(net)
        except Exception:
            return []

    initial = choose_starts(repaired, min(30, len(repaired)))
    for net in initial:
        if tools.lp_calls_left <= 0:
            break
        try:
            evaluate(net)
        except Exception as exc:
            if type(exc).__name__ == "BudgetExhausted":
                break
            continue

    if not seen:
        return list(initial[0])

    def archive():
        """Keep excellent networks and the best representatives of distinct regions."""
        ranked = sorted(seen, key=seen.get)
        out = []
        for net in ranked:
            if all(distance(net, old) >= 4 for old in out):
                out.append(net)
            if len(out) >= 24:
                break
        for net in ranked:
            if len(out) >= 32:
                break
            if net not in out:
                out.append(net)
        return out

    def select_parent(pop):
        """Balance elite exploitation with parent-level search productivity."""
        if not pop:
            return best_net
        pool = pop[:min(4, len(pop))] if rng.random() < 0.70 else pop
        weights = []
        for net in pool:
            visits = parent_visits.get(net, 0)
            improvements = parent_improvements.get(net, 0)
            stalls = parent_stalls.get(net, 0)
            weight = (1.0 + 1.5 * improvements) / ((1.0 + visits) ** 0.55)
            weight /= 1.0 + 0.12 * stalls
            weights.append(weight)
        probs = np.asarray(weights, dtype=float)
        probs /= probs.sum()
        parent = pool[int(rng.choice(len(pool), p=probs))]
        parent_visits[parent] = parent_visits.get(parent, 0) + 1
        return parent

    def switch(net, p, q):
        """Swap the destinations of two links, preserving all degrees."""
        arcs = list(net)
        (a, b), (c, d) = arcs[p], arcs[q]
        if a == d or c == b:
            return None
        cur = set(net)
        if (a, d) in cur or (c, b) in cur:
            return None
        cur.remove((a, b))
        cur.remove((c, d))
        cur.add((a, d))
        cur.add((c, b))
        return tuple(sorted(cur))

    def make_moves(net, detail):
        """Build a focused two-switch neighborhood plus sampled rotations and kicks."""
        arcs = list(net)
        current = set(net)
        moves = set()

        prices = detail.get("prices", {}) if detail else {}
        hot = {tuple(map(int, a)) for a, p in prices.items() if p > 0}
        if not hot and detail:
            loads = detail.get("loads", {})
            ranked_loads = sorted(
                ((float(v), tuple(map(int, a))) for a, v in loads.items()),
                reverse=True,
            )
            hot = {a for _, a in ranked_loads[:6]}

        # Exhaustively explore swaps involving at least one critical link.
        for p in range(len(arcs)):
            for q in range(p + 1, len(arcs)):
                if hot and arcs[p] not in hot and arcs[q] not in hot:
                    continue
                cand = switch(net, p, q)
                if cand is not None:
                    moves.add(cand)

        # Add non-focused swaps so that dual degeneracy cannot trap the search.
        for _ in range(70):
            if len(arcs) < 2:
                break
            p = int(rng.integers(len(arcs)))
            q = int(rng.integers(len(arcs) - 1))
            if q >= p:
                q += 1
            cand = switch(net, p, q)
            if cand is not None:
                moves.add(cand)

        # Escalate rotation sampling for parents whose neighborhoods have stalled.
        # Rotations preserve degrees and can cross barriers that two-switches miss.
        if len(arcs) >= 3:
            stalls = parent_stalls.get(net, 0)
            rotation_trials = min(350, 70 * (1 + stalls // 3))
            for _ in range(rotation_trials):
                ids = rng.choice(len(arcs), size=3, replace=False)
                (a, b), (c, d), (e, f) = (arcs[int(i)] for i in ids)
                old = {(a, b), (c, d), (e, f)}
                if hot and not (old & hot):
                    continue
                for new in (
                    {(a, d), (c, f), (e, b)},
                    {(a, f), (c, b), (e, d)},
                ):
                    if len(new) != 3 or any(x == y for x, y in new):
                        continue
                    if new & (current - old):
                        continue
                    cand = tuple(sorted((current - old) | new))
                    moves.add(cand)

        # Occasional multi-switch kicks broaden the neighborhood beyond one step.
        for _ in range(24):
            cur = set(net)
            for _ in range(2 + int(rng.integers(4))):
                arcs_now = list(cur)
                if len(arcs_now) < 2:
                    break
                p, q = rng.choice(len(arcs_now), size=2, replace=False)
                a, b = arcs_now[int(p)]
                c, d = arcs_now[int(q)]
                if a == d or c == b or (a, d) in cur or (c, b) in cur:
                    continue
                cur.remove((a, b))
                cur.remove((c, d))
                cur.add((a, d))
                cur.add((c, b))
            cand = tuple(sorted(cur))
            if cand != net:
                moves.add(cand)

        # Add intermediate networks on a short path toward a strong, distinct
        # archived solution. Each two-switch must increase overlap with the target.
        targets = [
            x for x in sorted(seen, key=seen.get)[:12]
            if x != net and distance(net, x) >= 6
        ]
        if targets:
            target = targets[int(rng.integers(len(targets)))]
            target_edges = set(target)
            path_net = net
            for _ in range(8):
                path_arcs = list(path_net)
                path_set = set(path_net)
                overlap = len(path_set & target_edges)
                improving = []
                for p in range(len(path_arcs)):
                    for q in range(p + 1, len(path_arcs)):
                        cand = switch(path_net, p, q)
                        if cand is not None:
                            gain = len(set(cand) & target_edges) - overlap
                            if gain > 0:
                                improving.append((gain, cand))
                if not improving:
                    break
                best_gain = max(g for g, _ in improving)
                choices = [cand for gain, cand in improving if gain == best_gain]
                path_net = choices[int(rng.integers(len(choices)))]
                moves.add(path_net)

        return [m for m in moves if m != net and tools.is_valid(m)]

    def screen_batch(moves, parent, batch_size=9):
        """Use surrogate ranking and topology distance to select an LP batch."""
        fresh = [
            m for m in moves
            if m not in seen and not tools.is_cached(m)
        ]
        if not fresh:
            return []

        base_e = energy(parent)
        ranked = []
        for net in fresh:
            ranked.append((energy(net) - base_e, net))
        ranked.sort(key=lambda item: item[0])

        selected = []
        stalls = parent_stalls.get(parent, 0)
        if stalls >= 2 and batch_size >= 3:
            # Retain two high-ranked trials, then spend one LP call exploring
            # beyond the surrogate's preferred neighborhood.
            for _, net in ranked:
                if all(distance(net, old) >= 2 for old in selected):
                    selected.append(net)
                if len(selected) >= 2:
                    break
            exploratory = [
                net for _, net in ranked
                if net not in selected
                and all(distance(net, old) >= 2 for old in selected)
            ]
            if not exploratory:
                exploratory = [net for _, net in ranked if net not in selected]
            if exploratory:
                rng.shuffle(exploratory)
                selected.append(exploratory[0])
        else:
            # First take good-energy moves that are not all tiny variants of one another.
            for _, net in ranked:
                if all(distance(net, old) >= 2 for old in selected):
                    selected.append(net)
                if len(selected) >= min(6, batch_size):
                    break

