    def two_switch(net, p, q):
        arcs = list(net)
        a, b = arcs[p]
        c, d = arcs[q]
        if a == d or c == b:
            return None

        current = edge_set(net)
        new1, new2 = (a, d), (c, b)
        if new1 in current or new2 in current:
