                ids = rng.choice(len(arcs), size=3, replace=False)
                (a, b), (c, d), (e, f) = (arcs[int(i)] for i in ids)
                old = {(a, b), (c, d), (e, f)}
                if hot and not (old & hot):
                    continue
                for new in (
                    {(a, d), (c, f), (e, b)},
                    {(a, f), (c, b), (e, d)},
                ):
                    if len(new) != 3 or any(x == y for x, y in new):
                        continue
                    if new & (current - old):
                        continue
                    cand = tuple(sorted((current - old) | new))
                    moves.add(cand)

        # Occasional multi-switch kicks broaden the neighborhood beyond one step.
        for _ in range(24):
            cur = set(net)
            for _ in range(2 + int(rng.integers(4))):
                arcs_now = list(cur)
                if len(arcs_now) < 2:
                    break
                p, q = rng.choice(len(arcs_now), size=2, replace=False)
                a, b = arcs_now[int(p)]
                c, d = arcs_now[int(q)]
                if a == d or c == b or (a, d) in cur or (c, b) in cur:
                    continue
                cur.remove((a, b))
                cur.remove((c, d))
                cur.add((a, d))
                cur.add((c, b))
            cand = tuple(sorted(cur))
            if cand != net:
                moves.add(cand)

        # Add intermediate networks on a short path toward a strong, distinct
        # archived solution. Each two-switch must increase overlap with the target.
        targets = [
            x for x in sorted(seen, key=seen.get)[:12]
            if x != net and distance(net, x) >= 6
        ]
        if targets:
            target = targets[int(rng.integers(len(targets)))]
            target_edges = set(target)
            path_net = net
            for _ in range(8):
                path_arcs = list(path_net)
                path_set = set(path_net)
                overlap = len(path_set & target_edges)
                improving = []
                for p in range(len(path_arcs)):
                    for q in range(p + 1, len(path_arcs)):
                        cand = switch(path_net, p, q)
                        if cand is not None:
                            gain = len(set(cand) & target_edges) - overlap
                            if gain > 0:
                                improving.append((gain, cand))
                if not improving:
                    break
                best_gain = max(g for g, _ in improving)
                choices = [cand for gain, cand in improving if gain == best_gain]
                path_net = choices[int(rng.integers(len(choices)))]
                moves.add(path_net)

        return [m for m in moves if m != net and tools.is_valid(m)]

    def screen_batch(moves, parent, batch_size=9):
        """Use surrogate ranking and topology distance to select an LP batch."""
        fresh = [
            m for m in moves
            if m not in seen and not tools.is_cached(m)
        ]
        if not fresh:
            return []

        base_e = energy(parent)
        ranked = []
        for net in fresh:
            ranked.append((energy(net) - base_e, net))
        ranked.sort(key=lambda item: item[0])

        selected = []
        stalls = parent_stalls.get(parent, 0)
        if stalls >= 2 and batch_size >= 3:
            # Retain two high-ranked trials, then spend one LP call exploring
            # beyond the surrogate's preferred neighborhood.
            for _, net in ranked:
                if all(distance(net, old) >= 2 for old in selected):
                    selected.append(net)
                if len(selected) >= 2:
                    break
            exploratory = [
                net for _, net in ranked
                if net not in selected
                and all(distance(net, old) >= 2 for old in selected)
            ]
            if not exploratory:
                exploratory = [net for _, net in ranked if net not in selected]
            if exploratory:
                rng.shuffle(exploratory)
                selected.append(exploratory[0])
        else:
            # First take good-energy moves that are not all tiny variants of one another.
            for _, net in ranked:
                if all(distance(net, old) >= 2 for old in selected):
                    selected.append(net)
                if len(selected) >= min(6, batch_size):
                    break

        # Fill remaining slots with the best surrogate-ranked moves.
        for _, net in ranked:
            if len(selected) >= batch_size:
                break
            if net not in selected:
                selected.append(net)

        # Reserve a little batch capacity for tail exploration.
        tail = [net for _, net in ranked if net not in selected]
        if tail and len(selected) >= 4 and len(selected) < batch_size:
            rng.shuffle(tail)
            selected.extend(tail[:batch_size - len(selected)])
        return selected[:batch_size]

    # A bounded archive drives a sequence of short, diverse neighborhood searches.
    rounds = 0
    while tools.lp_calls_left > 0:
        rounds += 1
        pop = archive()
        parent = select_parent(pop)
        if parent is None:
            break

        try:
            detail = tools.lp_detail(parent)
        except Exception:
            detail = None

        moves = make_moves(parent, detail)
        batch = screen_batch(moves, parent, batch_size=3)

        # If a neighborhood has already been exhausted, perturb another archive
        # member rather than repeatedly revisiting the same parent.
        if not batch:
            alternatives = [x for x in pop if x != parent]
            if alternatives:
                parent = alternatives[int(rng.integers(len(alternatives)))]
                parent_visits[parent] = parent_visits.get(parent, 0) + 1
                try:
                    detail = tools.lp_detail(parent)
                except Exception:
                    detail = None
                batch = screen_batch(make_moves(parent, detail), parent, batch_size=3)

        if not batch:
            # A final random degree-preserving kick guarantees progress when possible.
            for _ in range(40):
                cur = set(parent)
                arcs = list(cur)
                for _ in range(3 + int(rng.integers(4))):
                    p, q = rng.choice(len(arcs), size=2, replace=False)
                    a, b = arcs[int(p)]
                    c, d = arcs[int(q)]
                    if a == d or c == b or (a, d) in cur or (c, b) in cur:
                        continue
                    cur.remove((a, b))
                    cur.remove((c, d))
                    cur.add((a, d))
                    cur.add((c, b))
                    arcs = list(cur)
                kicked = tuple(sorted(cur))
                if kicked != parent and kicked not in seen and not tools.is_cached(kicked):
                    batch = [kicked]
                    break

        if not batch:
            # All available moves may be cached; avoid an unbounded spin.
            if rounds > 10000:
                break
            continue

        parent_score = seen.get(parent, float("inf"))
        for net in batch:
            if tools.lp_calls_left <= 0:
                break
            try:
                evaluate(net)
            except Exception as exc:
                if type(exc).__name__ == "BudgetExhausted":
                    return list(best_net) if best_net is not None else []
                continue

        batch_best = min((seen.get(net, float("inf")) for net in batch), default=float("inf"))
        if batch_best < parent_score:
            parent_stalls[parent] = 0
            parent_improvements[parent] = parent_improvements.get(parent, 0) + 1
        else:
            parent_stalls[parent] = parent_stalls.get(parent, 0) + 1

    return list(best_net) if best_net is not None else []
# EVOLVE-BLOCK-END


